import { useState } from 'react'
import { Button } from 'moru-ui'
import { Item, ItemContent, ItemTitle, ItemDescription, ItemActions } from 'moru-ui'

export function ProjectItem() {
  const [expanded, setExpanded] = useState(false)
  return (
    <Item variant="muted">
      <ItemContent>
        <ItemTitle>Project brief</ItemTitle>
        <ItemDescription>
          {expanded
            ? 'A shared outline of goals, milestones, and owners.'
            : 'A quick introduction.'}
        </ItemDescription>
      </ItemContent>
      <ItemActions>
        <Button
          type="button"
          size="sm"
          variant="secondary"
          aria-expanded={expanded}
          onClick={() => setExpanded((value) => !value)}
        >
          {expanded ? 'Less' : 'More'}
        </Button>
      </ItemActions>
    </Item>
  )
}

